    private void seedProductIfNotExists(String sku, String name, String description, String imageUrl, String images,
                                        BigDecimal costPrice, BigDecimal wholesalePrice, BigDecimal retailPrice,
                                        String categoryName, int minStock, boolean isPerishable) {
        if (!productRepository.existsBySku(sku)) {
            Category category = categoryRepository.findAll().stream()
                    .filter(c -> categoryName.equalsIgnoreCase(c.getName()) && !Boolean.TRUE.equals(c.getIsDeleted()))
                    .findFirst().orElse(null);
            if (category == null) {
                log.warn("[DataSeeder] Cannot seed product '{}' because category '{}' is missing.", sku, categoryName);
                return;
            }
            Product prod = Product.builder()
                    .sku(sku)
                    .name(name)
                    .description(description)
                    .imageUrl(imageUrl)
                    .images(images)
                    .costPrice(costPrice)
                    .wholesalePrice(wholesalePrice)
                    .retailPrice(retailPrice)
                    .category(category)
                    .minStockThreshold(minStock)
                    .isPerishable(isPerishable)
                    .isDeleted(false)
                    .build();
            productRepository.save(prod);
            log.info("[DataSeeder] Inserted missing product: {} (SKU: {})", name, sku);
        } else {
            log.debug("[DataSeeder] Product already exists in DB, skipping override: {}", sku);
        }
    }

