    private void seedBatchIfNotExists(String batchCode, String productSku, String supplierName,
                                      int initialQty, int currentQty, LocalDate expiryDate) {
        if (!productBatchRepository.existsByBatchCode(batchCode)) {
            Product product = productRepository.findAll().stream()
                    .filter(p -> productSku.equalsIgnoreCase(p.getSku()) && !Boolean.TRUE.equals(p.getIsDeleted()))
                    .findFirst().orElse(null);
            Supplier supplier = supplierRepository.findAll().stream()
                    .filter(s -> supplierName.equalsIgnoreCase(s.getName()) && !Boolean.TRUE.equals(s.getIsDeleted()))
                    .findFirst().orElse(null);

            if (product == null || supplier == null) {
                log.warn("[DataSeeder] Cannot seed batch '{}' because product or supplier is missing.", batchCode);
                return;
            }
            ProductBatch batch = ProductBatch.builder()
                    .batchCode(batchCode)
                    .product(product)
                    .supplier(supplier)
                    .initialQuantity(initialQty)
                    .currentQuantity(currentQty)
                    .expiryDate(expiryDate)
                    .isExpired(false)
                    .build();
            productBatchRepository.save(batch);
            log.info("[DataSeeder] Inserted missing product batch: {}", batchCode);
        } else {
            log.debug("[DataSeeder] ProductBatch already exists in DB, skipping override: {}", batchCode);
        }
    }

