    private void seedUserIfNotExists(String email, String rawPassword, String fullName,
                                     String phone, String roleName, CustomerType customerType,
                                     String addresses, String posPin, String avatarUrl, String companyName) {
        if (!userRepository.existsByEmail(email)) {
            Role role = roleRepository.findByName(roleName).orElse(null);
            if (role == null) {
                log.warn("[DataSeeder] Cannot seed user '{}' because role '{}' is missing.", email, roleName);
                return;
            }
            User user = User.builder()
                    .email(email)
                    .passwordHash(passwordEncoder.encode(rawPassword))
                    .fullName(fullName)
                    .phone(phone)
                    .role(role)
                    .customerType(customerType != null ? customerType : CustomerType.RETAIL)
                    .addresses(addresses != null && !addresses.isEmpty() ? addresses : "[]")
                    .posPin(posPin != null && !posPin.isEmpty() ? posPin : "1234")
                    .avatarUrl(avatarUrl)
                    .companyName(companyName)
                    .isActive(true)
                    .build();
            userRepository.save(user);
            log.info("[DataSeeder] Inserted missing baseline user: {} ({})", email, roleName);
        } else {
            log.debug("[DataSeeder] User already exists in DB, skipping override: {}", email);
        }
    }
